-- dwm workspaces in Rex's command palette.
--
-- Generated by `dwm setup`, which rewrites this file when dwm moves, so edits
-- here are lost. Bind the action to a key in init.lua, for example:
--
--   rex.bind("cmd+shift+w", "dwm_switch")

local DWM = "@DWM@"
local REX = "@REX@"
-- The PATH of the shell that ran `dwm setup`. Rex's own is minimal, and dwm
-- needs to find jj and git.
local PATH = "@PATH@"
local TERMINAL = "com.superlogical.terminal"
local SHELL = "com.superlogical.terminal.shell"

-- Programs Rex starts don't inherit a pane's environment, so tell dwm to use
-- Rex and where to find it, and that it isn't running in any pane.
local DWM_ENV = { PATH = PATH, DWM_REX = "1", DWM_REX_BIN = REX, REX_BLOCK = false, REX_SESSION = false }

local function list_workspaces(cwd)
  if cwd ~= nil then
    local r = rex.exec({ DWM, "status", "--json" }, { cwd = cwd, env = DWM_ENV, timeout = 30 })
    if r ~= nil and r.ok then
      return rex.json.decode(r.stdout)
    end
  end
  local r, err = rex.exec({ DWM, "status", "--all", "--json" }, { env = DWM_ENV, timeout = 60 })
  if r == nil then
    error("dwm: " .. tostring(err), 0)
  end
  if not r.ok then
    error("dwm: " .. r.stderr, 0)
  end
  return rex.json.decode(r.stdout)
end

local function agent_detail(agents)
  if agents == nil then
    return nil
  end
  local parts = {}
  for _, key in ipairs({ "waiting", "working", "done", "idle" }) do
    if (agents[key] or 0) > 0 then
      table.insert(parts, agents[key] .. " " .. key)
    end
  end
  if #parts == 0 then
    return nil
  end
  return table.concat(parts, ", ")
end

rex.action({
  name = "dwm_switch",
  title = "dwm: Switch Workspace…",
  description = "Focus a dwm workspace's pane, or open a session for it",
  category = "dwm",
  keywords = "workspace worktree jj git",
  run = function(ctx)
    -- List the repository of the focused pane, or every repository.
    local cwd
    if ctx.block_id ~= nil then
      local p = rex.block.call(TERMINAL, "process", { session_id = ctx.session_id, block_id = ctx.block_id })
      cwd = p and ((p.foreground and p.foreground.cwd) or (p.ancestors and p.ancestors[1] and p.ancestors[1].cwd))
    end
    -- Rex servers before control API revision 17 have no prompts. Open dwm's
    -- own picker in a floating pane instead; it focuses or opens a session for
    -- the chosen workspace the same way, then exits and the pane closes.
    if rex.ui == nil or rex.ui.pick == nil then
      local argv = { "/usr/bin/env", "DWM_REX_THROWAWAY_PANE=1", DWM, "list" }
      if cwd == nil then
        table.insert(argv, "--all")
      end
      local _, err = rex.session.new_layer({
        session_id = ctx.session_id,
        bounds = { 0.05, 0.08, 0.9, 0.84 },
        focus = true,
        layout = rex.layout.block({ flavor = SHELL, options = { command = argv, cwd = cwd or os.getenv("HOME") } }),
      })
      if err ~= nil then
        error("opening dwm's picker: " .. tostring(err), 0)
      end
      return
    end

    local listing = list_workspaces(cwd)

    local items, by_path = {}, {}
    for _, ws in ipairs(listing.workspaces or {}) do
      local title = ws.name
      if ws.repo ~= nil and ws.repo ~= "" then
        title = ws.repo .. " / " .. ws.name
      end
      -- What an agent there says it is doing beats the commit description.
      local subtitle = ws.description
      local note = ws.agents and ws.agents.notes and ws.agents.notes[1]
      if note ~= nil then
        subtitle = note.status .. ": " .. note.text
      elseif subtitle == nil or subtitle == "" then
        subtitle = ws.path
      end
      table.insert(items, {
        id = ws.path,
        title = title,
        subtitle = subtitle,
        icon = ws.rex_pane and "terminal" or "branch",
        detail = agent_detail(ws.agents),
      })
      by_path[ws.path] = ws
    end

    local path = rex.ui.pick({ title = "Switch workspace", placeholder = "Filter workspaces", items = items })
    if path == nil then
      return
    end
    local ws = by_path[path]

    if ws.rex_pane ~= nil then
      local pane = ws.rex_pane
      rex.call("session.attach", { session_id = pane.session_id })
      rex.call("session.focus_block", { session_id = pane.session_id, block_id = pane.block_id })
      rex.client.queue("session.select", { session_id = pane.session_id, window_id = pane.window_id })
      return
    end

    local created, err = rex.call("session.create", {
      label = ws.session_label or ws.name,
      initial_windows = {
        { layout = rex.layout.block({ flavor = SHELL, options = { cwd = ws.path } }) },
      },
    })
    if created == nil then
      error("creating session: " .. tostring(err), 0)
    end
    rex.client.queue("session.select", { session_id = created.session_id })
  end,
})
